def minFlipsToBalance(s):
    if len(s) % 2:
        return -1
    open_count = 0   # unmatched '{'
    stray_close = 0  # '}' with no '{' before it
    for ch in s:
        if ch == '{':
            open_count += 1
        elif open_count > 0:
            open_count -= 1
        else:
            stray_close += 1
    return (stray_close + 1) // 2 + (open_count + 1) // 2
